function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'closed'; // 'closed', 'open', 'half-open'
  let failureCount = 0;
  let openTime = 0;
  let halfOpenInProgress = false;

  function tryReset() {
    if (state === 'open' && Date.now() - openTime >= delaiResetMs) {
      state = 'half-open';
      halfOpenInProgress = false;
    }
  }

  return async function(...args) {
    if (state === 'open') {
      tryReset();
      if (state === 'open') {
        throw new Error('Circuit ouvert');
      }
    }

    if (state === 'half-open') {
      if (halfOpenInProgress) {
        throw new Error('Circuit ouvert (test en cours)');
      }
      halfOpenInProgress = true;
      try {
        const result = await fn(...args);
        // succès : fermer le circuit
        state = 'closed';
        failureCount = 0;
        halfOpenInProgress = false;
        return result;
      } catch (err) {
        // échec : rouvrir
        state = 'open';
        openTime = Date.now();
        halfOpenInProgress = false;
        throw err;
      }
    }

    // state === 'closed'
    try {
      const result = await fn(...args);
      failureCount = 0;
      return result;
    } catch (err) {
      failureCount++;
      if (failureCount >= seuil) {
        state = 'open';
        openTime = Date.now();
      }
      throw err;
    }
  };
}
```

