function remplirMatrice(grille, x, y, nouvelleValeur) {
  if (!grille || !grille.length || y < 0 || y >= grille.length || x < 0 || x >= grille[0].length) {
    return grille;
  }
  const valeurInitiale = grille[y][x];
  if (valeurInitiale === nouvelleValeur) {
    return grille;
  }
  const pile = [[x, y]];
  while (pile.length > 0) {
    const [cx, cy] = pile.pop();
    if (cx < 0 || cy < 0 || cy >= grille.length || cx >= grille[cy].length) continue;
    if (grille[cy][cx] !== valeurInitiale) continue;
    grille[cy][cx] = nouvelleValeur;
    pile.push([cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]);
  }
  return grille;
}
