function trier_tableau(arr) {
  // Tri fusion sans utiliser Array.prototype.sort()
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  const left = trier_tableau(arr.slice(0, mid));
  const right = trier_tableau(arr.slice(mid));
  return fusion(left, right);
}

function fusion(left, right) {
  const result = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i]);
      i++;
    } else {
      result.push(right[j]);
      j++;
    }
  }
  return result.concat(left.slice(i)).concat(right.slice(j));
}
